class Gradebook:
    def __init__(self, student_name, marks):
        self.student_name = student_name
        self.marks = marks  # List of numeric marks

    def total(self):
        return sum(self.marks)

    def average(self):
        return self.total() / len(self.marks) if self.marks else 0.0

    def is_pass(self, passing_score=40):
        # All individual marks must satisfy threshold
        return all(m >= passing_score for m in self.marks)

    def report(self):
        status = "PASSED" if self.is_pass() else "FAILED"
        print("===== STUDENT REPORT CARD =====")
        print(f"Name    : {self.student_name}")
        print(f"Marks   : {self.marks}")
        print(f"Total   : {self.total()}")
        print("Average : %.2f" % self.average())
        print(f"Result  : {status}")

card1 = Gradebook("Arun", [80, 75, 90, 85, 70])
card1.report()

