class StudentRecord:
    def __init__(self, name, mark):
        if not (0 <= mark <= 100):
            raise ValueError(f"Invalid score: {mark}")
        self.name = name
        self.mark = mark

    def is_pass(self):
        return self.mark >= 40

# Loading and parsing records with exception safeguards
cohort = []
try:
    with open('students_demo.txt', 'r') as file:
        for line in file:
            line = line.strip()
            if line:
                name, mark_str = line.split(',')
                student_obj = StudentRecord(name.strip(), int(mark_str.strip()))
                cohort.append(student_obj)
except FileNotFoundError:
    print("Database file not found!")

print("===== COHORT AUDIT =====")
for s in cohort:
    verdict = "Pass" if s.is_pass() else "Fail"
    print(f"Name: {s.name:<8} | Mark: {s.mark:>3} | Result: {verdict}")
print(f"Cohort Size: {len(cohort)} | Pass Count: {sum(1 for s in cohort if s.is_pass())}")
